update ea_records set data=jsonb_set(data,'{coverageNote}',to_jsonb('National parliamentary elections from 1874 through 2024, the 1844 election to the restored Althing, separate nationwide upper-house elections in 1916–1930, presidential selections and unopposed renewals from 1944 through 2024, and the subsequently annulled 2010 Constitutional Assembly election. Royal appointees are not portrayed as elected. Historical combined-house tables can include continuing upper-house members and identify that distinction. Five elections—1902, 1903, 1908, 1911 and 1914—have verified dates and turnout but no verified national party breakdown in this archive. Some historical vote allocations contain fractions, explained in their notes. No ballot totals or turnout are invented for unopposed returns.'::text)),updated=now() where id='world-country-is';
end $import$; commit;
